<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {ArrowRight,Check,Plus} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {getMigrations,getMigration,getPhaseProgress,createMigration,submitEntries,activateMigration} from '../api/phases';import {PhaseMigration,PhaseProgress,SplitEntry} from '../types/domain';import StudySelector from '../components/StudySelector.vue';import DataTable from '../components/common/DataTable.vue';import Notice from '../components/common/Notice.vue';import {MigrationStatus,VersionStatus,EntryStatus} from '../constants/enums';import {number,time} from '../utils/format';const s=useResearchData(),auth=useAuth(),a=useAction(),route=useRoute(),id=ref(Number(route.query.study)||0),progress=ref<PhaseProgress|null>(null),migrations=ref<PhaseMigration[]>([]),selected=ref<number>(Number(route.query.migration)||0),detail=ref<PhaseMigration|null>(null),batch=ref<Record<string,{a:string;b:string}>>({}),notice=ref(''),splitCode=ref(''),label=ref(''),newA=ref(''),newB=ref(''),labelA=ref(''),labelB=ref('');const study=computed(()=>s.studies.find(x=>x.id===id.value)||s.studies[0]);const editable=computed(()=>auth.user?.role!=='viewer');const canActivate=computed(()=>auth.user?.role==='admin');const activeVersion=computed(()=>progress.value?.active_version||null);const canCreate=computed(()=>editable.value&&!!activeVersion.value&&(activeVersion.value.status==='active')&&(s.components.length<6));
async function load(){if(!study.value)return;await s.loadStudy(study.value.id);try{const [p,m]=await Promise.all([getPhaseProgress(study.value.id),getMigrations(study.value.id)]);progress.value=p;migrations.value=m;if(!selected.value||!m.some(x=>x.id===selected.value))selected.value=m[0]?.id||0;await loadDetail()}catch(e){notice.value=(e as Error).message}}
async function loadDetail(){if(!selected.value){detail.value=null;batch.value={};return}try{const d=await getMigration(selected.value);const next:Record<string,{a:string;b:string}>={};for(const e of d.entries)if(e.status!=='confirmed')next[e.sample_code]={a:e.values[d.new_codes[0]]==null?'':String(e.values[d.new_codes[0]]),b:e.values[d.new_codes[1]]==null?'':String(e.values[d.new_codes[1]])};batch.value=next;detail.value=d}catch(e){notice.value=(e as Error).message}}
watch(()=>study.value?.id,async value=>{if(value){splitCode.value='';label.value='';newA.value='';newB.value='';labelA.value='';labelB.value='';selected.value=0;await load()}},{immediate:true});
function create(){a.execute(async()=>{notice.value='';const m=await createMigration(study.value.id,{label:label.value,split_code:splitCode.value,new_components:[{code:newA.value,label:labelA.value||newA.value},{code:newB.value,label:labelB.value||newB.value}]});selected.value=m.id;label.value='';await load()})}
function fillHalf(code:string,expected:number){const rest=expected/2;return {a:String(Math.round(rest*1e9)/1e9),b:String(Math.round((expected-rest)*1e9)/1e9)}}
function prefill(){if(!detail.value)return;for(const e of detail.value.entries){if(e.status==='confirmed'||e.expected_value==null)continue;const row=batch.value[e.sample_code];if(row&&(row.a||row.b))continue;batch.value[e.sample_code]=fillHalf(e.sample_code,e.expected_value)}}function submit(){if(!detail.value)return;a.execute(async()=>{notice.value='';const entries=detail.value!.entries.filter(e=>e.status!=='confirmed'&&e.expected_value!=null).map(e=>{const row=batch.value[e.sample_code]||{a:'',b:''};const values:Record<string,number>={};if(row.a!=='')values[detail.value!.new_codes[0]]=Number(row.a);if(row.b!=='')values[detail.value!.new_codes[1]]=Number(row.b);return {sample_code:e.sample_code,values}});if(!entries.length){notice.value='没有可补录的样本：缺少旧值的样本无法通过补录修正，请新建迁移或修复源版本。';return}const r=await submitEntries(detail.value!.id,entries);notice.value=r.duplicates_only?`本批 ${r.applied} 条新确认；${r.skipped.length} 条已确认值保持不变（不覆盖）`:`本批新确认 ${r.applied} 条；已确认 ${r.progress.confirmed}/${r.progress.total}`;await load()})}
function activate(){if(!detail.value)return;a.execute(async()=>{notice.value='';const r=await activateMigration(detail.value!.id);notice.value=`已整版切换到 v${r.target_version.version}「${r.target_version.label}」；上一版退役但仍可分析。`;await load()})}
function entryReason(e:SplitEntry){return e.status==='mismatch'?'和值不符':e.status==='invalid'?'补录无效':e.status==='pending'?'缺测未补录':'已确认'}
</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">PHASE CHANNEL MIGRATION / 03</p><h1>相通道迁移<span>分批补录拆分原量，全部核验后整版切换。</span></h1></div></div><Notice :message="s.error||a.error.value||notice" @retry="load"/><StudySelector :studies="s.studies" :model-value="study?.id||0" @update:model-value="id=$event"/><div v-if="progress" class="version-strip" aria-label="相通道版本状态"><div><span class="eyebrow">ACTIVE PHASE VERSION</span><b v-if="activeVersion">v{{activeVersion.version}} / {{activeVersion.label}}</b><b v-else>尚无版本</b><small>{{progress.version_count}} 个版本 · 旧版仍可分析，历史结果保留原相依据</small></div><div class="version-progress"><span class="eyebrow">IN PROGRESS</span><p v-for="m in progress.in_progress_progress" :key="m.migration_id">#{{m.migration_id}} {{m.label}} · {{m.progress.confirmed}}/{{m.progress.total}} 已确认 / {{m.progress.mismatch}} 和值不符 / {{m.progress.pending}} 待补录</p><p v-if="!progress.in_progress_progress.length">无进行中的迁移。</p></div></div><div class="migration-grid"><section><div class="section-heading"><h2>发起相通道拆分</h2><span>把一个通道拆成两个，其余保持原量</span></div><form v-if="canCreate" class="migration-create" @submit.prevent="create"><label>迁移名称<input aria-label="迁移名称" v-model="label" minlength="2" maxlength="160" required placeholder="例如：其余相拆为有机相与残余相"/></label><label>待拆分通道<select aria-label="待拆分通道" v-model="splitCode" required><option value="" disabled>选择当前版本中的一个通道</option><option v-for="c in s.components" :key="c.code" :value="c.code">{{c.label}}（{{c.code}}）</option></select></label><div class="form-row"><label>新通道 A 编号<input aria-label="新通道A编号" v-model="newA" required pattern="[A-Za-z0-9_.-]+" maxlength="40" placeholder="org"/></label><label>新通道 A 名称<input aria-label="新通道A名称" v-model="labelA" maxlength="80" placeholder="有机相"/></label></div><div class="form-row"><label>新通道 B 编号<input aria-label="新通道B编号" v-model="newB" required pattern="[A-Za-z0-9_.-]+" maxlength="40" placeholder="res"/></label><label>新通道 B 名称<input aria-label="新通道B名称" v-model="labelB" maxlength="80" placeholder="残余相"/></label></div><p class="caption">两个新通道之和须逐样本等于旧通道原量；其他通道保持原量。当前 {{s.components.length}} 个通道，拆分后 {{s.components.length+1}} 个（上限 6）。</p><button class="primary" :disabled="a.busy.value||!splitCode||!newA||!newB||newA===newB">建立迁移草稿 <Plus :size="15"/></button></form><p v-else-if="editable" class="caption">当前版本通道数已达 6 个上限，不能再拆分。</p><p v-else class="role-note">阅读者可查看迁移进度；发起与补录需要研究员权限。</p><div class="section-heading"><h2>全部迁移</h2><span>竞争迁移只有一版生效</span></div><DataTable :head="['#','名称','目标版本','状态','进度']"><tr v-for="m in migrations" :key="m.id" :class="{selected:m.id===selected}" @click="selected=m.id;loadDetail()"><td>{{m.id}}</td><td>{{m.label}}</td><td>v{{m.target_version.version}}</td><td><span :class="['review-badge',m.status]">{{MigrationStatus[m.status]}}</span></td><td><small>{{m.progress.confirmed}}/{{m.progress.total}} 已确认<template v-if="m.progress.mismatch"> · {{m.progress.mismatch}} 和值不符</template><template v-if="m.status==='invalidated'"> · 本版失效</template></small></td></tr></DataTable><p v-if="!migrations.length" class="empty">尚无迁移。先在左侧发起一次拆分。</p><div v-if="detail" class="migration-detail"><div class="section-heading"><h2>{{detail.label}}</h2><span>#{{detail.id}} · {{detail.split_code}} → {{detail.new_codes.join(' / ')}} · {{MigrationStatus[detail.status]}}</span></div><div class="migration-meta"><p><b>源版本</b>v{{detail.source_version?.version}} / {{detail.source_version?.label}} <span :class="['review-badge',detail.source_version?.status||'']">{{VersionStatus[(detail.source_version?.status||'draft') as keyof typeof VersionStatus]}}</span></p><p><b>目标版本</b>v{{detail.target_version.version}} <span :class="['review-badge',detail.target_version.status]">{{VersionStatus[detail.target_version.status]}}</span></p><p v-if="detail.status==='invalidated'" class="warning"><b>失效原因</b>{{detail.invalidated_reason}}</p><p v-if="detail.status==='activated'"><b>切换时间</b>{{time(detail.activated_at)}}</p></div><div v-if="detail.status==='in_progress'" class="progress-bar"><span :style="{width:(detail.progress.total?detail.progress.confirmed/detail.progress.total*100:0)+'%'}"/></div><p v-if="detail.status==='in_progress'" class="caption">已确认 {{detail.progress.confirmed}}/{{detail.progress.total}} · 和值不符 {{detail.progress.mismatch}} · 补录无效 {{detail.progress.invalid}} · 待补录 {{detail.progress.pending}}。<template v-if="detail.progress.confirmed===detail.progress.total">全部核验通过，可由材料负责人整版切换。</template></p><DataTable :head="['样本','旧通道原量',detail.new_codes[0],detail.new_codes[1],'和值','状态','说明']"><tr v-for="e in detail.entries" :key="e.id"><td>{{e.sample_code}}</td><td>{{number(e.expected_value,6)}}</td><td><input v-if="detail.status==='in_progress'&&e.status!=='confirmed'&&e.expected_value!=null" aria-label="拆分原量A" class="cell-input" type="number" min="0" step="any" v-model="batch[e.sample_code].a" :class="{bad:e.status==='invalid'||e.status==='mismatch'}"/><span v-else>{{e.expected_value==null&&e.status!=='confirmed'?'不可补录':number(e.values[detail.new_codes[0]],6)}}</span></td><td><input v-if="detail.status==='in_progress'&&e.status!=='confirmed'&&e.expected_value!=null" aria-label="拆分原量B" class="cell-input" type="number" min="0" step="any" v-model="batch[e.sample_code].b" :class="{bad:e.status==='invalid'||e.status==='mismatch'}"/><span v-else>{{e.expected_value==null&&e.status!=='confirmed'?'不可补录':number(e.values[detail.new_codes[1]],6)}}</span></td><td>{{e.submitted_sum==null?'—':number(e.submitted_sum,6)}}</td><td><span :class="['entry-badge',e.status]">{{EntryStatus[e.status]}}</span></td><td class="reason-cell">{{e.status==='confirmed'?'二者之和与旧值一致':e.reason||entryReason(e)}}</td></tr></DataTable><div v-if="detail.status==='in_progress'" class="migration-actions"><button v-if="editable" class="outline" :disabled="a.busy.value||!detail.entries.some(e=>e.status!=='confirmed')" @click="submit">保存本批补录</button><button v-if="editable&&detail.entries.some(e=>e.status!=='confirmed')" class="outline" @click="prefill">按旧值二分预填</button><button v-if="canActivate" class="primary" :disabled="a.busy.value||!detail.progress.complete" @click="activate"><Check :size="15"/>整版切换</button><span v-else-if="!canActivate" class="caption">整版切换需要材料负责人权限。</span></div><div v-else-if="detail.status==='activated'" class="migration-actions"><RouterLink class="outline" :to="'/inputs?study='+study?.id">查看新版本通道 <ArrowRight :size="14"/></RouterLink></div></div></section><aside class="method-note"><span class="eyebrow">MIGRATION NOTE / 31</span><h2>拆分不改和，<br/>切换才换版。</h2><ol><li><b>逐样本核验</b><p>两个新原量之和须等于旧通道原量；其他相保持原量。缺测、和值不符或含非法通道都会列出原因，并阻止切换。</p></li><li><b>可中断续补</b><p>补录按批保存；中断后可从任意未确认样本继续。已确认值不覆盖，修正需新建迁移。</p></li><li><b>整版切换与并发</b><p>全部核验后一次性切换到目标版本。旧版退役但仍可分析；竞争迁移只有一版生效，另一版明确失效。切换与研究创建并发时，冻结的通道和样本来自同一版。</p></li><li><b>历史结果</b><p>历史运行与获批导出保留其运行时的旧相依据，不随新版本改写。</p></li></ol></aside></div></div></template>
